import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const failing = (reason: unknown): AIProvider =>
  ({
    sendMessage: () => ({
      [Symbol.asyncIterator]: () => ({next: () => Promise.reject(reason)}),
    }),
  }) as unknown as AIProvider;

const observe = async (reason: unknown) => {
  const seen: Error[] = [];
  const session = {
    sessionId: 's',
    userId: 'u',
    entries: [{role: 'user', content: 'hi', timestamp: '2026-01-01T00:00:00.000Z'}],
  } as ChatSession;
  const orchestrator = createChatOrchestrator(
    failing(reason),
    new PromptBuilder({identity: 'test'}),
    undefined,
    {hooks: {onError: async (_s, error) => void seen.push(error)}}
  );
  const thrown = await orchestrator.processMessage(session).catch((e: unknown) => e);
  return {seen, thrown};
};

describe('ChatOrchestrator onError wrapping', () => {
  const reasons: [string, unknown][] = [
    ['a string', 'string boom'],
    ['a plain object', {code: 503}],
    ['undefined', undefined],
  ];

  it.each(reasons)('wraps %s as the cause of the Error handed to onError', async (_label, reason) => {
    const {seen} = await observe(reason);

    expect(seen.map(e => [e instanceof Error, e.cause])).toEqual([[true, reason]]);
  });

  it.each(reasons)('rethrows %s to the caller unchanged', async (_label, reason) => {
    const {thrown} = await observe(reason);

    expect(thrown).toBe(reason);
  });

  it('passes an Error through to onError as the same instance', async () => {
    const reason = new Error('boom');

    const {seen} = await observe(reason);

    expect(seen).toEqual([reason]);
  });
});
EOF
